                    odds_selecoes.append(escolha_extra["odd"])
                    detalhes_bilhete.append(f"• **{partida_extra} (Bônus Master)** ➔ `{escolha_extra['nome']}` (Odd: `{escolha_extra['odd']}`)")
                    odd_final_multipla = calcular_odd_criar_aposta(odds_selecoes)
