            {"num": "10", "nome": "Kevin De Bruyne", "pos": "Meia", "media_gols": 0.40, "ultimas_5_chutes": [3, 2, 3, 2, 3], "ult.5_faltas_sofridas": [3, 4, 3, 3, 4], "ult.5_faltas_cometidas": [1, 1, 1, 0, 1]}
