            {"num": "17", "nome": "Vinicinho", "pos": "Atacante", "media_gols": 0.40, "ultimas_5_chutes": [2,3,2,3,3], "ult.5_faltas_sofridas": [3,2,3,3,4], "ult.5_faltas_cometidas": [1,1,1,2,1]}
