            {"num": "10", "nome": "Ryan Christie", "pos": "Meia", "media_gols": 0.15, "ultimas_5_chutes": [1, 1, 2, 1, 1], "ult.5_faltas_sofridas": [2, 2, 1, 2, 2], "ult.5_faltas_cometidas": [3, 2, 3, 2, 3]}
