    st.markdown("### 📊 Dossiê de Elencos (Elencos Oficiais Atualizados via API)")
    if not df_jogos.empty:
        op_d = [f"{r['Mandante']} x {r['Visitante']} ({r['Liga Categoria']})" for _, r in df_jogos.iterrows()]
