            elenco_m = obter_elenco_api_real(m_nome)
            elenco_v = obter_elenco_api_real(v_nome)
            
            c1, c2 = st.columns(2)
            with c1:
                st.markdown(f"### 🏠 {m_nome}")
                for p in elenco_m:
                    with st.container(border=True):
                        st.markdown(f"**Camisa #{p['num']} — {p['nome']}** ({p['pos']})")
