def renderizar_confianca(prob_pct):
    if prob_pct >= 60:
        st.success(f"🟢 **Alta Assertividade ({prob_pct}%) — Zona de Alta Confiança (60-100%)**")
    else:
        st.warning(f"🟡 **Assertividade Moderada ({prob_pct}%)**")

